INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'','فیلتر و تنظیم فشار سیستم آبیاری قطره‌ای در مهردشت','','inherit','open','closed','لوله-نخی-تاشو-مهردشت-یزد-looleh-nakhi-tashoo-جزئیات-فنی',NOW(),UTC_TIMESTAMP(),@post_id,'https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/لوله-نخی-تاشو-مهردشت-یزد-looleh-nakhi-tashoo-جزئیات-فنی.webp',0,'attachment','image/webp',0 WHERE @created_post=1 AND @media_3 IS NULL;
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @media_3,'_wp_attached_file','2026/09/navar-city-generated/لوله-نخی-تاشو-مهردشت-یزد-looleh-nakhi-tashoo-جزئیات-فنی.webp' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@media_3 AND meta_key='_wp_attached_file');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @media_3,'_wp_attachment_image_alt','فیلتر و تنظیم فشار سیستم آبیاری قطره‌ای در مهردشت' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@media_3 AND meta_key='_wp_attachment_image_alt');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @post_id,'_thumbnail_id',@media_1 WHERE @created_post=1 AND @media_1 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@post_id AND meta_key='_thumbnail_id');
